Algoritmo Saludo
  Definir nombre Como Cadena <- "Ana";
  Escribir "Hola, " + nombre + '!';
  Escribir 'a' + 'b', " ", Longitud('a' + 'b');
FinAlgoritmo

Algoritmo ConNumero
  Definir edad Como Entero <- 12;
  Escribir "Tienes " + ConvertirATexto(edad) + " años";
  Escribir "Tienes ", edad, " años";
FinAlgoritmo
